Here is the JavaScript implementation of the Bubble Sort algorithm. It includes strict input validation based on your constraints, error handling, and detailed comments explaining the logic and time complexity.

```javascript
/**
 * Sorts an array of integers in ascending order using the Bubble Sort algorithm.
 * 
 * Algorithm Logic:
 * Bubble Sort works by repeatedly stepping through the list, comparing adjacent elements,
 * and swapping them if they are in the wrong order. The pass through the list is repeated
 * until the list is sorted. The algorithm gets its name because smaller elements "bubble"
 * to the top of the list (beginning) while larger elements sink to the bottom (end).
 * 
 * Complexity Analysis:
 * - Time Complexity (Average/Worst): O(n^2) - Occurs when the array is in reverse order.
 * - Time Complexity (Best): O(n) - Occurs when the array is already sorted (due to the 'swapped' flag optimization).
 * - Space Complexity: O(1) - Auxiliary space, as it sorts in-place (though we clone the input here to avoid mutation).
 * 
 * @param {number[]} inputArr - The array of integers to sort.
 * @returns {number[]} - A new array containing the sorted integers.
 * @throws {Error} - Throws if input is invalid or violates constraints.
 */
function bubbleSort(inputArr) {
    // --- Configuration Constants ---
    const MAX_LENGTH = 100;
    const MIN_VAL = -10000;
    const MAX_VAL = 10000;

    // --- Input Validation ---

    // 1. Check if input is an array
    if (!Array.isArray(inputArr)) {
        throw new Error("Invalid Input: Input must be an array.");
    }

    // 2. Check array length constraint
    if (inputArr.length > MAX_LENGTH) {
        throw new Error(`Invalid Input: Array length exceeds the maximum limit of ${MAX_LENGTH}.`);
    }

    // 3. Validate elements (Integer check and Range check)
    for (let i = 0; i < inputArr.length; i++) {
        const num = inputArr[i];

        if (!Number.isInteger(num)) {
            throw new Error(`Invalid Input: Element at index ${i} is not an integer.`);
        }

        if (num < MIN_VAL || num > MAX_VAL) {
            throw new Error(`Invalid Input: Element at index ${i} (${num}) is out of range. Values must be between ${MIN_VAL} and ${MAX_VAL}.`);
        }
    }

    // --- Algorithm Implementation ---

    // Create a shallow copy to avoid mutating the original array (Pure Function)
    let arr = [...inputArr];
    let n = arr.length;
    let swapped;

    // Outer loop: controls the number of passes
    for (let i = 0; i < n - 1; i++) {
        swapped = false;

        // Inner loop: compares adjacent elements
        // Optimization: We subtract 'i' because the last 'i' elements are already sorted
        for (let j = 0; j < n - i - 1; j++) {

            // Compare adjacent elements
            if (arr[j] > arr[j + 1]) {
                // Swap if they are in the wrong order (Ascending)
                let temp = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = temp;

                swapped = true;
            }
        }

        // Optimization: If no two elements were swapped by the inner loop, then the array is sorted.
        // This prevents unnecessary iterations on an already sorted array.
        if (!swapped) {
            break;
        }
    }

    return arr;
}

// --- Usage Examples ---

try {
    // Example 1: Valid Input
    const data = [64, -34, 25, 12, 22, 11, 90];
    console.log("Original Array:", data);
    const sortedData = bubbleSort(data);
    console.log("Sorted Array:  ", sortedData);

} catch (error) {
    console.error(error.message);
}

console.log("\n--- Error Handling Tests ---");

// Example 2: Testing Length Constraint
try {
    const longArray = new Array(101).fill(1);
